pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Keep the admissible domain wide: any non-zero actor, and any
        // destination different from the caller (the interesting case).
        vm.assume(actor != address(0));
        vm.assume(newOwner != actor);

        // The contract starts with owner == address(0), so bootstrap the
        // ownership chain from there: 0 -> actor -> newOwner.
        vm.prank(address(0));
        c.transferOwnership(actor);

        // The current owner transfers ownership to a different address.
        vm.prank(actor);
        c.transferOwnership(newOwner);

        // General rule: after a successful transferOwnership(n) by the owner,
        // the stored owner is exactly n — a guarded call must not leave
        // owner pointing at the caller instead.
        assertTrue(c.owner() == newOwner);
    }
}

