pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address n, address s) public {
        vm.assume(a != address(0));
        vm.assume(n != a);
        vm.assume(s != n);

        // owner starts at address(0); set initial owner to a through the public surface
        vm.prank(address(0));
        c.transferOwnership(a);

        // current owner a transfers ownership to n
        vm.prank(a);
        c.transferOwnership(n);

        // Rule: after transferring ownership to n, a call from unrelated party s (s != n)
        // to the guarded function owned() must revert — guarded calls must not confer
        // ownership or mutate owner as a side effect.
        bool ok;
        vm.prank(s);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

