pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Rule 1: a non-owner caller must be rejected: transferOwnership reverts.
        vm.prank(caller);
        bool okNonOwner;
        try c.transferOwnership(newOwner) { okNonOwner = true; } catch { okNonOwner = false; }

        // Rule 2: the current owner (initially address(0)) succeeds and sets the new owner.
        vm.prank(address(0));
        bool okOwner;
        try c.transferOwnership(newOwner) { okOwner = true; } catch { okOwner = false; }

        assertTrue(!okNonOwner && okOwner && c.owner() == newOwner);
    }
}

